static void DSTDigestquantile(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 2);
    auto &sketch_vector = args.data[0];
    auto &rank_vector = args.data[1];
    DSSketchCache<DSTDigestSketch<DSItem<T>>> sketch_cache;
    BinaryExecutor::Execute<string_t, double, T>(sketch_vector, rank_vector, result, [&](string_t sketch_data, double rank_data) {
        return DSGuard("datasketch_tdigest_quantile", [&]() {
            const auto &sketch = sketch_cache.Get(sketch_data, "TDigest");
            DSCheckRank(rank_data); return DSItemOut<T>(result, sketch.get_quantile(rank_data));
        });
    });
}

template <class T>
static void DSTDigestmerge(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 2);
    auto &sketch_a_vector = args.data[0];
    auto &sketch_b_vector = args.data[1];
    DSSketchCache<DSTDigestSketch<DSItem<T>>> sketch_a_cache;
    DSSketchCache<DSTDigestSketch<DSItem<T>>> sketch_b_cache;
    BinaryExecutor::Execute<string_t, string_t, string_t>(sketch_a_vector, sketch_b_vector, result, [&](string_t sketch_a_data, string_t sketch_b_data) {
        return DSGuard("datasketch_tdigest_merge", [&]() {
            const auto &sketch_a = sketch_a_cache.Get(sketch_a_data, "TDigest");
            const auto &sketch_b = sketch_b_cache.Get(sketch_b_data, "TDigest");
            auto merged = sketch_a;
            DSMergeSketch(merged, sketch_b);
            return DSAddBytes(result, merged.serialize());
        });
    });
}

template <class T>
static void DSTDigestmin_value(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 1);
    auto &sketch_vector = args.data[0];
    DSSketchCache<DSTDigestSketch<DSItem<T>>> sketch_cache;
    UnaryExecutor::Execute<string_t, T>(sketch_vector, result, [&](string_t sketch_data) {
        return DSGuard("datasketch_tdigest_min_value", [&]() {
            const auto &sketch = sketch_cache.Get(sketch_data, "TDigest");
            return sketch.get_min_value();
        });
    });
}

template <class T>
static void DSTDigestmax_value(DataChunk &args, ExpressionState &state, Vector &result) {
    D_ASSERT(args.ColumnCount() == 1);
    auto &sketch_vector = args.data[0];
    DSSketchCache<DSTDigestSketch<DSItem<T>>> sketch_cache;
    UnaryExecutor::Execute<string_t, T>(sketch_vector, result, [&](string_t sketch_data) {
        return DSGuard("datasketch_tdigest_max_value", [&]() {
            const auto &sketch = sketch_cache.Get(sketch_data, "TDigest");
            return sketch.get_max_value();
        });
    });
}

template <class T>
static AggregateFunction DSTDigestMergeAggregate(const LogicalType &type, const LogicalType &result_type) {
    if constexpr (!std::is_same_v<T, string_t>) {
        using STATE = DSTDigestArenaState<T>;
        using OP = DSArenaMergeOperation<DSTDigestBindData>;
        auto fun = AggregateFunction::UnaryAggregate<STATE, string_t, string_t, OP>(result_type, result_type);
        DSReadDataArgumentAt<1, STATE, string_t, OP>(fun);
        DSSetArenaStateExport<STATE, DSTDigestBindData>(fun);
        return fun;
    }
    using OP = DSQuantilesMergeOperation<DSTDigestBindData>;
    auto fun = AggregateFunction::UnaryAggregate<DSTDigestState<T>, string_t, string_t, OP, AggregateDestructorType::LEGACY>(result_type, result_type);
    DSReadDataArgumentAt<1, DSTDigestState<T>, string_t, OP>(fun);
    return fun;
}

template <class T>
static AggregateFunction DSTDigestCreateAggregate(const LogicalType &type, const LogicalType &result_type) {
    if constexpr (!std::is_same_v<T, string_t>) {
        using STATE = DSTDigestArenaState<T>;
        using OP = DSArenaCreateOperation<DSTDigestBindData>;
        auto fun = AggregateFunction::UnaryAggregate<STATE, T, string_t, OP>(type, result_type);
        DSReadDataArgumentAt<1, STATE, T, OP>(fun);
        DSSetArenaStateExport<STATE, DSTDigestBindData>(fun);
        return fun;
    }
    using OP = DSQuantilesCreateOperation<DSTDigestBindData>;
    auto fun = AggregateFunction::UnaryAggregate<DSTDigestState<T>, T, string_t, OP, AggregateDestructorType::LEGACY>(type, result_type);
    DSReadDataArgumentAt<1, DSTDigestState<T>, T, OP>(fun);
    return fun;
}

